entries[112450] = { ["name"] = "Glyph of Leer of the Ox", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ethereal Ink (3)\nMajor Glyph\nClasses: Monk\n25\nUse: Permanently teaches you this glyph.\n\nTeaches you the spell Leer of the Ox.\n\nLeer of the Ox\nYour Ox Statue stirs hatred in the target, reducing their movement speed by 50% and causing them to attack your Black Ox Statue for 8 sec. The statue must be within 40 yards of the target.\n\nRequires Black Ox Statue to be active." }
entries[112451] = { ["name"] = "Glyph of Afterlife", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Jadefire Ink (3)\nMajor Glyph\nClasses: Monk\n25\nUse: Permanently teaches you this glyph.\n\nIncreases the chance to summon a Healing Sphere when you kill an enemy while gaining experience or honor to 100%." }
