entries[112457] = { ["name"] = "Glyph of Fortifying Brew", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Shimmering Ink (3)\nMajor Glyph\nClasses: Monk\n25\nUse: Permanently teaches you this glyph.\n\nYour Fortifying Brew reduces damage taken by an additional 5%, but increases your health by 10% rather than 20%." }
entries[112458] = { ["name"] = "Glyph of Targeted Expulsion", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of the Sea (3)\nMajor Glyph\nClasses: Monk\n25\nUse: Permanently teaches you this glyph.\n\n[ Mistweaver : Outside of Battlegrounds and Arenas:\nYour Uplift no longer costs Chi, but instead costs 10% Mana.\n\nInside of Battlegrounds and Arenas: ]Expel Harm can now be used on other allies, but the healing is reduced by 50% on them." }
entries[112460] = { ["name"] = "Glyph of Zen Flight", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMinor Glyph\nClasses: Monk\n25\nUse: Permanently teaches you this glyph.\n\nTeaches you the spell Zen Flight. Zen Flight requires a Flight Master's License in order to be cast.\n\nZen Flight\nYou fly through the air at a quick speed on a meditative cloud." }
entries[112461] = { ["name"] = "Glyph of Water Roll", ["text"] = "3 sec cast 3\nTools: Virtuoso Inking Set\nReagents:\nLight Parchment , Ink of Dreams (3)\nMinor Glyph\nClasses: Monk\n25\nUse: Permanently teaches you this glyph.\n\nYou can Roll or Chi Torpedo over water." }
