entries[112859] = { ["name"] = "Holy Insight", ["text"] = "Increases the effectiveness of your healing by 25% and your Word of Glory, Eternal Flame and Light of Dawn by 50%.\n\nIncreases your mana pool by 400%.\n\nAllows 50% of your mana regeneration from Spirit to continue while in combat.\n\nIncreases your chance to hit with Holy Shock, Judgment, [ Glyph of Harsh Words : Harsh Words ]and Denounce by 15%.\n\nGrants hit and expertise equal to 50% Spirit gained from items or effects while outside of Arenas and Battlegrounds." }
