entries[112866] = { ["name"] = "Summon Fel Imp", ["text"] = "20% of base mana / 20% of base demonic fury\n5 sec cast\nSummons a Fel Imp under the command of the Warlock.\n\nFel Imps cast ranged Fel Firebolts [ Imp: Cauterize Master : can heal their master over time ] [ Imp: Singe Magic : cleanse hostile magic effects ] . [ Soulburn : Soulburn:\nInstant cast. ]" }
entries[112867] = { ["name"] = "Summon Voidlord", ["text"] = "25% of base mana / 20% of base demonic fury\n5 sec cast\nSummons a Voidlord under the command of the Warlock.\n\nVoidlords can withstand heavy punishment [ Voidwalker: Disarm : disarm melee attackers ] [ Voidwalker: Shadow Shield : deal Shadow damage to enemies who harm them ] [ Voidwalker: Shadow Bulwark : increase their health when near death ] [ Voidwalker: Suffering : and taunt enemies attacking their master / . ] [ Soulburn : Soulburn:\nInstant cast. ]" }
entries[112868] = { ["name"] = "Summon Shivarra", ["text"] = "25% of base mana / 20% of base demonic fury\n5 sec cast\nSummons a Shivarra under the command of the Warlock.\n\nShivarra are dangerous, close-range spellcasters. They [ Succubus: Lesser Invisibility : turn invisible ] [ Succubus: Whiplash : knock away enemies ] [ Succubus: Lesser Invisibility : and ] mesmerize opponents, preventing them from attacking. [ Soulburn : Soulburn:\nInstant cast. ]" }
entries[112869] = { ["name"] = "Summon Observer", ["text"] = "25% of base mana / 20% of base demonic fury\n5 sec cast\nSummons an Observer under the command of the Warlock.\n\nObservers are drawn to magic [ Felhunter: Spell Lock : use powerful optical attacks which interrupt spellcasting ] and heal themselves by stealing beneficial magic effects from enemies. [ Soulburn : Soulburn:\nInstant cast. ]" }
entries[112870] = { ["name"] = "Summon Wrathguard", ["text"] = "25% of base mana / 20% of base demonic fury\n5 sec cast\nSummons a Wrathguard under the command of the Warlock.\n\nWrathguard are powerful melee fighters who excel against multiple targets [ Felguard: Felstorm : can perform a powerful area attack ] [ Felguard: Axe Toss : stun an opponent at range ] and greatly reduce healing received by their target." }
